  ('0b0d579c-326a-57ff-a214-05f4f1be73dd'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"La bouteille oubliée au congélateur","competence":"raisonner","situation":"Inès a mesuré sa bouteille avant et après le congélateur, puis elle en parle avec Léo. À vous deux de trouver ce qui s’est passé.","documents":[{"id":"mesures","type":"tableau","titre":"Avant et après le congélateur","colonnes":["Grandeur","Avant (eau liquide)","Après (glace)"],"lignes":[["Masse","500 g","500 g"],["Volume","500 mL","545 mL"]],"enteteLignes":true,"source":"Valeurs arrondies, écrites pour l’exercice"},{"id":"dialogue","type":"dialogue","modele":"sms","titre":"Dans la cuisine","participants":[{"nom":"Inès","emoji":"👧","cote":"gauche"},{"nom":"Léo","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Inès","texte":"J’ai rempli une bouteille de 500 mL à ras bord et je l’ai oubliée au congélateur. Elle a craqué !"},{"qui":"Léo","texte":"Normal : la glace, c’est une autre matière que l’eau. Elle fait craquer la bouteille."}]}],"questions":[{"enonce":"Touche la case du tableau qui explique pourquoi la bouteille a craqué.","aide":"La bouteille ne peut contenir que 500 mL : cherche la valeur qui dépasse.","type":"zone","document":"mesures","multiple":false},{"enonce":"De combien de millilitres le volume a-t-il augmenté en gelant ?","aide":"Fais la différence entre le volume après et le volume avant.","type":"nombre","unite":"mL"},{"enonce":"Que peut-on répondre à Léo ?","aide":"Regarde la ligne « Masse » du tableau, puis relis ce que dit le cours sur un changement d’état.","type":"choix","options":[{"id":"a","texte":"Tu as raison : la glace est une substance différente"},{"id":"b","texte":"La glace n’existe que dans les congélateurs"},{"id":"c","texte":"La glace est de l’eau, mais elle pèse moins que l’eau"},{"id":"d","texte":"La glace est de l’eau : seul l’état a changé"}],"multiple":false},{"enonce":"Relie chaque grandeur à ce qui lui arrive quand l’eau gèle.","aide":"Reprends les deux lignes du tableau et la remarque de Léo.","type":"association","gauche":[{"id":"g0",