   $ex${"titre":"Un message codé en points et traits","competence":"resoudre","situation":"Théo et Inès communiquent avec une lampe de poche et un code à deux signes : un point (flash court) et un trait (flash long). Inès vient de recevoir un message.","documents":[{"id":"code","type":"tableau","titre":"Le code de Théo","colonnes":["Lettre","Signal"],"lignes":[["A","• –"],["E","•"],["I","• •"],["N","– •"],["O","– – –"],["S","• • •"],["T","–"]],"enteteLignes":true,"source":"Code inspiré du morse, écrit pour l’exercice"},{"id":"message","type":"texte","genre":"consigne","titre":"Le message reçu par Inès","blocs":["Les lettres sont séparées par une barre :","– •   /   – – –   /   –   /   •"]}],"questions":[{"enonce":"Décode le message : quel mot Théo a-t-il envoyé ?","aide":"Décode lettre par lettre grâce au tableau, en lisant de gauche à droite.","type":"texte","placeholder":"Le mot"},{"enonce":"Combien de signaux (points et traits) Théo a-t-il envoyés en tout ?","aide":"Compte les signaux de chaque lettre, puis additionne.","type":"nombre","unite":"signaux"},{"enonce":"Dans cet échange, qui décode le message ?","aide":"Pense à l’émetteur, au canal et au récepteur.","type":"choix","options":[{"id":"a","texte":"Personne : le message se décode tout seul"},{"id":"b","texte":"Théo, qui est l’émetteur"},{"id":"c","texte":"Inès, qui est le récepteur"},{"id":"d","texte":"La lampe de poche, qui est le canal"}],"multiple":false},{"enonce":"Ce code n’a que deux signes. Quel langage numérique lui ressemble ?","aide":"Cherche un code à deux états seulement.","type":"choix","options":[{"id":"a","texte":"Le wifi, avec ses ondes"},{"id":"b","texte":"La fibre, avec son fil de verre"},{"id":"c","texte":"Le binaire, avec ses 0 et ses 1"},{"id":"d","texte":"Le français, avec ses 26 lettres"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"texte","acceptes":["note"]},"affichage":"note","explication":"– • = N ; – – – = O ; – = T ; • = E. Le mot est **NOTE**."},{"cle":{"type":"nombre","valeur":7,"tolerance":0},"affichage":"7 signaux","explication":"2 + 3 + 1 + 1 = **7 signaux**."},{"cle":{"type":"choix","ids":["c"]},"explication":"**Inès**, le récepteur, décode ce que **Théo**, l’émetteur, a codé. Les flashs sont le canal."},{"cle":{"type":"choix","ids":["c"]},"explication":"Le **binaire** n’a que deux états, 0 et 1, comme les points et les traits : tout texte, image ou son peut être codé avec deux signes."}]$ex$::jsonb),
