otides"},{"id":"g2","texte":"Lipides"},{"id":"g3","texte":"Fibres"}],"droite":[{"id":"d0","texte":"Carburant principal"},{"id":"d1","texte":"Font fonctionner l’intestin"},{"id":"d2","texte":"Réserve d’énergie"},{"id":"d3","texte":"Matériaux de construction"}]}]}$ex$::jsonb,
